import sys

def solve():
    t = sys.stdin.readline().strip()
    sbegin = sys.stdin.readline().strip()
    send = sys.stdin.readline().strip()

    n = len(t)
    len_sbegin = len(sbegin)
    len_send = len(send)

    # Find all valid start positions where sbegin appears as a prefix
    start_positions = []
    for i in range(n - len_sbegin + 1):
        if t[i:i+len_sbegin] == sbegin:
            start_positions.append(i)

    # Find all valid end positions where send appears as a suffix
    end_positions = []
    for j in range(len_send - 1, n):
        if t[j - len_send + 1:j + 1] == send:
            end_positions.append(j)

    # Count unique valid substrings
    unique_substrings = set()

    for start in start_positions:
        for end in end_positions:
            # Check if the substring from start to end is valid
            # The substring must start with sbegin and end with send
            if end >= start + len_sbegin - 1:
                substring = t[start:end + 1]
                unique_substrings.add(substring)

    print(len(unique_substrings))

if __name__ == "__main__":
    solve()
