import sys

def solve():
    s, x = map(int, sys.stdin.readline().split())

    if s < x:
        print(0)
        return

    diff = s - x
    if diff % 2 != 0:
        print(0)
        return

    y = diff // 2
    if (y & x) != 0:
        print(0)
        return

    k = bin(x).count('1')
    if y == 0:
        print(2 ** k - 2)
    else:
        print(2 ** k)

if __name__ == '__main__':
    solve()
