import sys

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)
    if n <= 1:
        print("Just a legend")
        return

    # Compute prefix function
    prefix = [0] * n
    for i in range(1, n):
        j = prefix[i-1]
        while j > 0 and s[i] != s[j]:
            j = prefix[j-1]
        if s[i] == s[j]:
            j += 1
        prefix[i] = j

    # Find all lengths that are both prefix and suffix
    candidates = set()
    for l in range(1, n):
        if prefix[-1] == l:
            candidates.add(l)

    # Sort candidates descending
    candidates = sorted(candidates, reverse=True)

    # Check each candidate
    for l in candidates:
        # Check if this prefix appears somewhere in the string as a substring (not just at the ends)
        # We can do this by checking if there is any position j > 0 and j < n-l where prefix[j] == l
        found = False
        for i in range(1, n - l):
            if prefix[i] == l:
                found = True
                break
        if found:
            print(s[:l])
            return

    print("Just a legend")

if __name__ == "__main__":
    solve()
"}

