import sys
from collections import defaultdict, deque

def find_bridges(n, adj):
    visited = [False] * (n + 1)
    disc = [0] * (n + 1)
    low = [0] * (n + 1)
    time = [1]
    bridges = set()

    def dfs(u, parent):
        visited[u] = True
        disc[u] = low[u] = time[0]
        time[0] += 1

        for v in adj[u]:
            if v == parent:
                continue
            if not visited[v]:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.add((min(u, v), max(u, v)))
            else:
                low[u] = min(low[u], disc[v])

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, -1)
    return bridges

def count_reachable(n, adj, exclude_edge):
    visited = [False] * (n + 1)

    def dfs(u):
        if not visited[u]:
            visited[u] = True
            for v in adj[u]:
                if v == exclude_edge[0] or v == exclude_edge[1]:
                    continue
                dfs(v)

    # Try to reach the first node
    start = exclude_edge[0]
    dfs(start)
    return sum(visited)

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    adj = [[] for _ in range(n + 1)]
    edges = []

    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        adj[u].append(v)
        adj[v].append(u)
        edges.append((u, v))

    bridges = find_bridges(n, adj)

    result = 0

    for u, v in bridges:
        # Count vertices reachable from u without using this bridge
        count_u = count_reachable(n, adj, (u, v))
        # Count vertices reachable from v without using this bridge
        count_v = count_reachable(n, adj, (v, u))

        result += min(count_u, count_v)

    print(result)

if __name__ == "__main__":
    solve()
"}

