def fenwick_tree(size):
    return [0] * (size + 1)


def fenwick_update(tree, index, value):
    while index < len(tree):
        tree[index] += value
        index += index & -index


def fenwick_query(tree, index):
    result = 0
    while index > 0:
        result += tree[index]
        index -= index & -index
    return result


def range_add(tree, l, r, value):
    fenwick_update(tree, l, value)
    fenwick_update(tree, r + 1, -value)


def main():
    import sys
    input = sys.stdin.read().split()
    it = iter(input)

    n = int(next(it))
    m = int(next(it))

    # Create Fenwick Trees
    a_tree = fenwick_tree(n)
    b_tree = fenwick_tree(n)

    # Initial values for array a and b
    a = [0] * (n + 1)
    for i in range(1, n + 1):
        a[i] = int(next(it))

    b = [0] * (n + 1)
    for i in range(1, n + 1):
        b[i] = int(next(it))

    # Process queries
    for _ in range(m):
        t = int(next(it))
        if t == 1:
            # Copy operation
            x = int(next(it))
            y = int(next(it))
            k = int(next(it))

            # Add a[x..x+k-1] to b[y..y+k-1]
            for i in range(x, x + k):
                # a[i] gets added to b[y + (i - x)]
                target_b_index = y + (i - x)
                range_add(b_tree, target_b_index, target_b_index, a[i])
        else:
            # Query operation
            x = int(next(it))
            result = fenwick_query(b_tree, x) + b[x]
            print(result)

if __name__ == "__main__":
    main()
