def factorize(n):
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n //= 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n //= i
        i += 2
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

def get_signature(n, k):
    # Get signature: reduce each exponent modulo k
    signature = {}
    for p, e in factorize(n).items():
        signature[p] = e % k
    return signature

n, k = map(int, input().split())
a = list(map(int, input().split()))

# Count frequency of each signature
from collections import defaultdict
signature_freq = defaultdict(int)

for num in a:
    signature = get_signature(num, k)
    # To make signatures comparable, sort by prime and convert to tuple
    sorted_signature = tuple(sorted(signature.items()))
    signature_freq[sorted_signature] += 1

result = 0

# For each signature, find its complement and count pairs
for signature, count in signature_freq.items():
    complement = {}
    for p, e in signature.items():
        complement[p] = (k - e) % k
    # Check if the complement signature exists
    sorted_complement = tuple(sorted(complement.items()))
    if sorted_complement in signature_freq:
        result += count * signature_freq[sorted_complement]

print(result)
