    left_min = [(-float('inf'), -1)] * n
    current_min = float('inf')
    for i in range(n):
        if a[i] < current_min:
            current_min = a[i]
            left_min[i] = (current_min, i)
        else:
            left_min[i] = left_min[i-1]

    # Precompute max values from left
    left_max = [(-float('inf'), -1)] * n
    current_max = -float('inf')
    for i in range(n):
        if a[i] > current_max:
            current_max = a[i]
            left_max[i] = (current_max, i)
        else:
            left_max[i] = left_max[i-1]

    # Precompute min values from right
    right_min = [(-float('inf'), -1)] * n
    current_min = float('inf')
    for i in range(n-1, -1, -1):
