if k == 0:
    result = a.copy()
else:
    for i in range(n):
        # Sum over all m from 0 to i (0-indexed)
        total = 0
        for m in range(i + 1):
            # binomial(i - m + k - 1, k - 1)
            # = binomial((i - m + k - 1), (i - m))
            n_comb = i - m + k - 1
            r_comb = i - m
            if r_comb == 0:
                comb = 1
            else:
                comb = 1
                for j in range(1, r_comb + 1):
                    comb = comb * (n_comb - r_comb + j) // j
            total += a[m] * comb
        result[i] = total

