def get_primes(n):
    """Return list of primes less than n using sieve of Eratosthenes"""
    if n < 2:
        return []
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n, i):
                is_prime[j] = False
    return [i for i, val in enumerate(is_prime) if val]

def get_previous(n):
    """Return all possible previous values that could lead to n in one turn"""
    primes = get_primes(n)
    prev_values = set()

    # For each prime, consider all possible previous numbers
    for p in primes:
        # If p divides n, n could come from n itself (player picked p and it already divided)
        if n % p == 0:
            prev_values.add(n)

        # Also consider the range of numbers that could lead to n by picking prime p
        # The smallest multiple of p >= M is ((M // p) + 1) * p
        # We want ((M // p) + 1) * p = n
        # => M could be any number in [((n-1)//p)*p, n-1] that is not divisible by p
        lower_bound = ((n - 1) // p) * p
        for m in range(lower_bound, n):
            if m % p != 0:
                prev_values.add(m)

    return sorted(prev_values)

def find_min_x0(X2):
    """Find minimum X0 such that after 2 turns we get X2"""
    # Find all possible X1 that could lead to X2 in one turn
    possible_X1 = get_previous(X2)

    min_X0 = float('inf')

    # For each X1, find all possible X0 that could lead to X1 in one turn
    for x1 in possible_X1:
        possible_X0 = get_previous(x1)
        if possible_X0:
            min_X0 = min(min_X0, min(possible_X0))

    return min_X0

# Read input and output result
