import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    p = float(data[1])
    t = int(data[2])

    # dp[i][j] = expected number of people on escalator with i people left after j seconds
    dp = [[0.0 for _ in range(t + 1)] for _ in range(n + 1)]

    # Base case: no people left, 0 on escalator
    for j in range(t + 1):
        dp[0][j] = 0.0

    # Fill DP table
    for i in range(1, n + 1):
        for j in range(1, t + 1):
            dp[i][j] = p * (dp[i-1][j-1] + 1.0) + (1 - p) * dp[i][j-1]

    print(f"{dp[n][t]:.12f}")

if __name__ == "__main__":
    solve()
