def find_bridges(n, m, edges):
    adj = [[] for _ in range(n + 1)]
    for i, (u, v) in enumerate(edges):
        adj[u].append((v, i))
        adj[v].append((u, i))

    time = 1
    disc = [0] * (n + 1)
    low = [0] * (n + 1)
    visited = [False] * (n + 1)
    is_bridge = [False] * m

    def dfs(u, parent):
        nonlocal time
        visited[u] = True
        disc[u] = low[u] = time
        time += 1

        for v, idx in adj[u]:
            if v == parent:
                continue
            if not visited[v]:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    is_bridge[idx] = True
            else:
                low[u] = min(low[u], disc[v])

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, -1)

    return sum(is_bridge)

n, m = map(int, input().split())
edges = []
for _ in range(m):
    u, v = map(int, input().split())
    edges.append((u, v))

result = find_bridges(n, m, edges)
