def count_ways(s, index, memo):
    """Return all possible ways to partition from index to end where each group sums to 9"""
    if index == len(s):
        return [()]

    if index in memo:
        return memo[index]

    ways = []

    # Try to form a group starting at index
    current_sum = 0
    for j in range(index, len(s)):
        current_sum += int(s[j])

        if current_sum == 9:
            # Recursively find ways to partition the rest
            rest = count_ways(s, j + 1, memo)
            for way in rest:
                ways.append((j, way))  # j is the end index of this group
        elif current_sum > 9:
            break

    memo[index] = ways
    return ways


