    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        s = next(it)
        t_str = next(it)

        # Check if character counts match
        if sorted(s) != sorted(t_str):
            out_lines.append('-1')
            continue

        # Find positions where s and t differ
        diff_positions = []
        for i in range(n):
            if s[i] != t_str[i]:
                diff_positions.append(i)

        # Count contiguous blocks of differing positions
        blocks = 0
        in_block = False
        for pos in diff_positions:
            if not in_block:
                blocks += 1
                in_block = True
            else:
                # Check if contiguous with previous position
                if pos == diff_positions[-1] + 1:
                    in_block = True
                else:
                    in_block = False

        out_lines.append(str(blocks))

    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    solve()
