    grid = [[0] * m for _ in range(n)]

    for _ in range(k):
        typ = int(next(it))
        idx = int(next(it)) - 1  # 0-indexed
        val = int(next(it))

        if typ == 1:
            for j in range(m):
                grid[idx][j] = val
        else:
            for i in range(n):
                grid[i][idx] = val

