    # Trace back through operations
    for op in reversed(operations):
        if op[0] == 1:
            # Type 1: add one element
            if p == 1:
                return op[1]
            else:
                p -= 1
        else:
            # Type 2: copy first l elements c times
            l = op[1]
            c = op[2]
            if p <= l:
                # It was in the original prefix
                pass
            else:
                # It was in one of the copied blocks
                # Determine which block it came from
                block_size = l
                # Position in the block: p - l
                # Which block: (p - l - 1) // block_size
                block = (p - l - 1) // block_size
                # Position in the block: ((p - l - 1) % block_size) + 1
                p = ((p - l - 1) % block_size) + 1

    return p  # If we reach here, it's from the initial empty sequence (shouldn't happen)

