import sys
from collections import deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    data = list(map(int, data))
    n = data[0]
    m = data[1]

    # Read the grid
    grid = []
    idx = 2
    for i in range(n):
        row = data[idx:idx+m]
        grid.append(row)
        idx += m

    # Find the center(s)
    centers = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                # Check if this could be the center
                count = 0
                for di in [-1, 0, 1]:
                    for dj in [-1, 0, 1]:
                        if di == 0 and dj == 0:
                            continue
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == 1:
                            count += 1
                if count == 4:  # Center has 4 adjacent 1's
                    centers.append((i, j))

    if not centers:
        print(-1)
        return

    # Try all k > 1
    results = []
    for k in range(2, 1000):  # k > 1, max possible k is around 1000
        # Check if this k is valid
        if is_valid(n, m, grid, k, centers):
            results.append(k)

    if results:
        print(' '.join(map(str, results)))
    else:
        print(-1)

def is_valid(n, m, grid, k, centers):
    # For each center, try BFS to find a valid path
    for (si, sj) in centers:
        visited = set()
        visited.add((si, sj))
        queue = deque([(si, sj, visited)])

        while queue:
            i, j, visited = queue.popleft()

            # Check if we've covered all 1's
            if all(grid[x][y] == 1 for x, y in visited):
                # Check if we can return to the start
                if (i, j) == (si, sj):
                    return True
                continue

            # Try all four directions
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni = i + di * k
                nj = j + dj * k

                if 0 <= ni < n and 0 <= nj < m:
                    # Check if we've crossed the same boundary twice
                    crossed = False
                    for (xi, xj) in visited:
                        # Check if this move crosses the boundary from (xi, xj)
                        if ni + di * k == xi and nj + dj * k == xj:
                            crossed = True
                            break
                    if not crossed:
                        new_visited = visited.copy()
                        new_visited.add((ni, nj))
                        queue.append((ni, nj, new_visited))

    return False

if __name__ == "__main__":
    solve()
