            for di, dj in [(0, k), (0, -k), (k, 0), (-k, 0)]:
                # Check if move is valid
                next_i = start_i + di
                next_j = start_j + dj
                if 0 <= next_i < n and 0 <= next_j < m:
                    # Track visited edges
                    visited_edges = {(start_i, start_j, next_i, next_j) if start_i <= next_i and start_j <= next_j else (next_i, next_j, start_i, start_j)}

                    # Track visited cells
                    visited_cells = {(start_i, start_j), (next_i, next_j)}

                    # Current position
                    current_i, current_j = next_i, next_j

                    def dfs(current_i, current_j, visited_cells, visited_edges):
                        # Check if all 1 cells are covered
                        if len(visited_cells) == len(ones):
                            return True

                        # Try all possible next moves
                        for di2, dj2 in [(0, k), (0, -k), (k, 0), (-k, 0)]:
