{"code": "
import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    MOD = 1000000007

    idx = 0
    h = int(data[idx]); idx += 1
    w = int(data[idx]); idx += 1

    r = [int(data[idx + i]) for i in range(h)]; idx += h
    c = [int(data[idx + j]) for j in range(w)]; idx += w

    count = 0
    for i in range(h):
        for j in range(w):
            # Check if cell (i+1, j+1) must be full

            # Row constraint: r_i > 0 and columns 1 to r_i are full
            # So if r_i > 0 and j+1 <= r_i, then full
            row_full = r[i] > 0 and (j + 1) <= r[i]

            # Column constraint: c_j > 0 and rows 1 to c_j are full
            # So if c_j > 0 and i+1 <= c_j, then full
            col_full = c[j] > 0 and (i + 1) <= c[j]

            if row_full or col_full:
                count += 1

    # Now check consistency: If r_i > 0, then cell (i+1, r_i) must be full
    # And if r_i = 0, then cell (i+1, 1) must be empty
    # Similarly for columns

    for i in range(h):
        # Row i: If r_i > 0, then columns 1 to r_i must be full
        # If r_i = 0, then column 1 must be empty
        if r[i] > 0:
            for j in range(r[i]):
                if (i + 1, j + 1) not in all_cells:
                    all_cells[(i + 1, j + 1)] = True
        elif r[i] == 0:
            if (i + 1, 1) not in all_cells:
                all_cells[(i + 1, 1)] = False

    for j in range(w):
        # Column j: If c_j > 0, then rows 1 to c_j must be full
        # If c_j = 0, then row 1 must be empty
        if c[j] > 0:
            for i in range(c[j]):
                if (i + 1, j + 1) not in all_cells:
                    all_cells[(i + 1, j + 1)] = True
        elif c[j] == 0:
            if (1, j + 1) not in all_cells:
                all_cells[(1, j + 1)] = False

    free_cells = h * w - count
    result = pow(2, free_cells, MOD)

    print(result)

if __name__ == "__main__":
    solve()
"}

