    idx = 0
    h = int(data[idx]); idx += 1
    w = int(data[idx]); idx += 1

    r = [int(data[idx + i]) for i in range(h)]; idx += h
    c = [int(data[idx + j]) for j in range(w)]; idx += w

    # Track which cells are fixed
    fixed = [[None for _ in range(w)] for _ in range(h)]  # None means not fixed

    for i in range(h):
        # Row i: If r_i > 0, then columns 1 to r_i must be full
        #        If r_i == 0, then column 1 must be empty
        if r[i] > 0:
            for j in range(r[i]):
                fixed[i][j] = True
        elif r[i] == 0:
            fixed[i][0] = False

    for j in range(w):
        # Column j: If c_j > 0, then rows 1 to c_j must be full
        #        If c_j == 0, then row 1 must be empty
        if c[j] > 0:
            for i in range(c[j]):
                fixed[i][j] = True
        elif c[j] == 0:
            fixed[0][j] = False

    # Check for conflicts
    for i in range(h):
        for j in range(w):
            if fixed[i][j] is not None:
                if (r[i] > 0 and (j + 1) <= r[i]) or (c[j] > 0 and (i + 1) <= c[j]):
                    continue
                # Conflict: The constraint says this cell should be fixed, but the row/column constraint doesn't cover it
                print(0)
                return

    # Count the number of free cells (None means not fixed)
    count = sum(1 for i in range(h) for j in range(w) if fixed[i][j] is None)

    result = pow(2, count, MOD)
    print(result)

if __name__ == "__main__":
