import sys

def solve():
    # Read input
    line = sys.stdin.readline().strip()
    if not line:
        return

    # Parse input
    h, m = map(int, line.split(':'))

    # Calculate angles
    hour_angle = (h % 12) * 30 + m * 0.5
    minute_angle = m * 6

    # Helper function to format numbers
    def format_number(num):
        # Check if number is an integer
        if num.is_integer():
            return str(int(num))
        # Check if we need one decimal place
        elif num * 10.0 == int(num * 10.0):
            return f"{int(num * 10.0)}/10"
        # Otherwise, use standard formatting
        else:
            return f"{num:.10f}".rstrip('0').rstrip('.')

    # Print formatted output
    print(f"{hour_angle:.10f} {minute_angle:.10f}")

if __name__ == "__main__":
    solve()
