import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    p = float(data[1])
    t = int(data[2])

    # Calculate geometric series sum 1 + p + p^2 + ... + p^k
    def geometric_sum(p, k):
        if k < 0:
            return 0.0
        if p == 1.0:
            return k + 1.0
        return (1.0 - pow(p, k + 1)) / (1.0 - p)

    result = 0.0

    for i in range(1, n + 1):
        if i > t:
            continue

        # Person i can enter at time k where k ranges from i to t
        # For each k, the probability is p * (1-p)^{(k-1) * (i-1)}
        # This is a geometric series with first term a = p and common ratio r = (1-p)^{i-1}

        a = p
        r = pow(1.0 - p, i - 1)

        # Number of terms = t - i + 1
        num_terms = t - i + 1

        # Sum of geometric series
        if r == 1.0:
            sum_series = a * num_terms
        else:
            sum_series = a * (1.0 - pow(r, num_terms)) / (1.0 - r)

        result += sum_series

    print(f"{result:.12f}")

if __name__ == "__main__":
    solve()
"}

