            divisors.add(i)
            while n % i == 0:
                n //= i
        i += 2
    if n > 1:
        divisors.add(n)
    return divisors

def solve(X2):
    # Find all prime divisors of X2
    primes = prime_divisors(X2)

    # Find all possible X1 values that could lead to X2
    possible_X1 = set()
    for p in primes:
        for x1 in range(X2 - p + 1, X2 + 1):
            possible_X1.add(x1)

    # Now find all possible X0 values for each X1
    min_X0 = float('inf')
    for x1 in possible_X1:
