def prime_sieve(n):
    """Find all primes up to n using sieve"""
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    return [i for i, prime in enumerate(is_prime) if prime]

def solve(X2):
    primes = prime_sieve(X2)

    # BFS from X2 back to X0
    visited = set()
    queue = [X2]

    while queue:
        current = queue.pop(0)
        visited.add(current)

        # Find all primes less than current
        prev_primes = [p for p in primes if p < current]

        # For each prime, find all possible previous numbers
        for p in prev_primes:
            start = current - p + 1
            for prev in range(start, current + 1):
                if prev not in visited:
                    queue.append(prev)

    # Find the minimum X0 that is reachable and ≥ 3
    min_X0 = float('inf')
    for x in visited:
        if x >= 3:
            min_X0 = min(min_X0, x)

    return min_X0

X2 = int(input())
print(solve(X2))
