    possible_X1 = set()
    for p in primes:
        for x1 in range(X2 - p + 1, X2 + 1):
            possible_X1.add(x1)

    # Now find all possible X0 values for each X1
    min_X0 = float('inf')
    for x1 in possible_X1:
        x1_primes = prime_divisors(x1)
        possible_X0 = set()
        for p in x1_primes:
            for x0 in range(x1 - p + 1, x1 + 1):
