def prime_divisors(n):
    """Find all prime divisors of n"""
    divisors = set()
    if n % 2 == 0:
        divisors.add(2)
        while n % 2 == 0:
            n //= 2
    i = 3
    while i * i <= n:
        if n % i == 0:
            divisors.add(i)
            while n % i == 0:
                n //= i
        i += 2
    if n > 1:
        divisors.add(n)
    return divisors

def solve(X2):
    # Find all possible X1 values that could lead to X2
    # For a prime p < X2, X1 could be in [X2 - p + 1, X2]
    possible_X1 = set()

    # Find all primes up to X2
    primes = prime_divisors(X2)
    for p in primes:
        if p < X2:
            for x1 in range(X2 - p + 1, X2 + 1):
                possible_X1.add(x1)

    # Now find all possible X0 values for each X1
    min_X0 = float('inf')
    for x1 in possible_X1:
        # Find all primes up to x1
        primes = prime_divisors(x1)
        for p in primes:
            if p < x1:
                for x0 in range(x1 - p + 1, x1 + 1):
                    min_X0 = min(min_X0, x0)

    return min_X0

