    """Count numbers <= x with exactly k ones in binary representation"""
    if k > x.bit_length():
        return 0

    # Count numbers with exactly k ones in binary representation <= x
    count = 0
    # Iterate through all positions for the leftmost 1
    for left in range(k, x.bit_length() + 1):
        # Place a 1 at the left position
        temp = 1 << (left - 1)
        # Count numbers with the remaining ones in the right part
        # We need to place (k-1) ones in the (left-1) rightmost bits
        count += bin(temp + (1 << (left - 1)) - 1).count('1')

