def count_pairs(n, k, arr):

    # Precompute smallest prime factors
    max_val = max(arr)
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, max_val + 1, i):
                spf[j] = min(spf[j], i)

    # Function to factorize a number
    def factorize(x):
        factors = {}
        while x > 1:
            p = spf[x]
            count = 0
            while x % p == 0:
                x //= p
                count += 1
            factors[p] = count
        return factors

    # Function to compute f factor
    def get_f(x, k):
        factors = factorize(x)
        f = 1
        for p, cnt in factors.items():
            # cnt = q * k + r
            r = cnt % k
            # r goes to f
            while r > 0:
                f *= p
                r -= 1
        return f

    # Function to compute complement of f
    def get_complement(f, k):
        if f == 1:
            return 1
        factors = factorize(f)
        complement = 1
        for p, cnt in factors.items():
            r = cnt % k
            if r > 0:
                # Need k - r more to make it a multiple of k
                while r < k:
                    complement *= p
                    r += 1
        return complement

    # Count frequencies of f factors
    freq = {}
    for num in arr:
        f = get_f(num, k)
        freq[f] = freq.get(f, 0) + 1

    # Count pairs
    count = 0
    for f, cnt in freq.items():
        complement = get_complement(f, k)

        # If f == complement, count combinations
        if f == complement:
            count += cnt * (cnt - 1) // 2
        else:
            # Count pairs with complement
            count += cnt * freq.get(complement, 0)
    return count

