# Read input
s = input().strip()

# Dynamic programming approach
dp = [{} for _ in range(len(s) + 1)]  # dp[i] tracks subsequences ending at position i

# Base case: empty string
for c in s:
    dp[0][c] = 1

# Fill DP table
for i in range(1, len(s) + 1):
    for j in range(i):
        # We can form subsequences ending at i by extending subsequences ending at j
        # This is for the case where the common difference is i-j
        for subseq, count in dp[j].items():
            if subseq[-1] == s[i-1]:
                # The last character in the subsequence matches the current character
                # We can extend the subsequence by one character
                new_subseq = subseq + s[i-1]
                dp[i][new_subseq] = dp[i].get(new_subseq, 0) + count
            # We can also start a new subsequence with the current character alone
            if len(dp[i]) == 0 or s[i-1] not in dp[i]:
                dp[i][s[i-1]] = 1

# Count all subsequences
all_subsequences = {}
for subseq, count in dp[len(s)].items():
    all_subsequences[subseq] = all_subsequences.get(subseq, 0) + count

# Find the maximum count
result = max(all_subsequences.values())

print(result)
