import sys

def solve():
    data = sys.stdin.read().strip().splitlines()
    if len(data) < 3:
        return
    t = data[0]
    sbegin = data[1]
    send = data[2]

    # Find all start indices where sbegin matches prefix
    start_matches = []
    n_sbegin = len(sbegin)
    for i in range(len(t) - n_sbegin + 1):
        if t[i:i+n_sbegin] == sbegin:
            start_matches.append(i)

    # Find all end indices where send matches suffix
    end_matches = []
    n_send = len(send)
    for j in range(n_send - 1, len(t)):
        if t[j - n_send + 1:j+1] == send:
            end_matches.append(j)

    # Collect unique substrings
    seen = set()
    for i in start_matches:
        for j in end_matches:
            if i <= j:
                seen.add(t[i:j+1])

    print(len(seen))

if __name__ == "__main__":
    solve()
