            end_matches.append(j)

    # Collect unique substrings
    seen = set()
    max_len = max(n_sbegin, n_send)
    for i in start_matches:
        for j in end_matches:
            if i <= j and j >= i + max_len - 1:
                seen.add(t[i:j+1])

    print(len(seen))

