# Find non-beautiful numbers
def is_beautiful(num):
    s = str(num)
    if s.count('1') > 1 or s.count('0') + s.count('1') != len(s):
        return False
    return True

non_beautiful = [num for num in numbers if not is_beautiful(num)]

if len(non_beautiful) == 0:
    # All beautiful, multiply them
    # Each beautiful number is 10^k, so we need sum of k's zeros
    # Start with 1, then add zeros
    sum_zeros = 0
    for num in numbers:
        if num != 1:
            sum_zeros += len(str(num)) - 1
    result = '1' + '0' * sum_zeros
    print(result)
elif len(non_beautiful) == 1:
    # Multiply all beautiful numbers
    sum_zeros = 0
    for num in numbers:
        if num != non_beautiful[0]:
            sum_zeros += len(str(num)) - 1

    # Multiply by non-beautiful number
    beautiful_part = '1' + '0' * sum_zeros

    # If beautiful_part is very large, we can't convert to int directly
    # Let's check the length
    if len(beautiful_part) > 100:
        print(beautiful_part + str(non_beautiful[0]))
    else:
        print(int(beautiful_part) * non_beautiful[0])
else:
    # Shouldn't happen, but handle case with multiple non-beautiful numbers
    # Just multiply normally
    print(int(numbers[0]) * int(numbers[1]) * int(numbers[2]) * int(numbers[3]) * int(numbers[4]))
