def count_pairs(n, k, nums):

    # Factorize a number into prime exponents modulo k
    def factorize_mod(num, k):
        if num == 1:
            return {}

        prime_factors = {}
        divisor = 2
        while divisor * divisor <= num:
            count = 0
            while num % divisor == 0:
                num //= divisor
                count += 1
            if count > 0:
                prime_factors[divisor] = count % k
            divisor += 1

        if num > 1:
            prime_factors[num] = 1 % k

        return prime_factors

    # Count occurrences of each signature
    signature_count = {}

    for num in nums:
        sig = factorize_mod(num, k)
        sig_tuple = tuple(sorted(sig.items()))

        if sig_tuple in signature_count:
            signature_count[sig_tuple] += 1
        else:
            signature_count[sig_tuple] = 1

    result = 0

    # Check all pairs of signatures
    for s1 in signature_count:
        count1 = signature_count[s1]

        # Find complement signature
        comp_sig = {}
        for prime, exp in s1.items():
            comp_sig[prime] = (k - exp) % k

        comp_tuple = tuple(sorted(comp_sig.items()))

        if comp_tuple in signature_count:
            count2 = signature_count[comp_tuple]

            if s1 == comp_tuple:
                # Self-pairs: choose 2 from count1
                result += count1 * (count1 - 1) // 2
            else:
                # Cross-pairs
                result += count1 * count2

    # Each pair was counted twice, so divide by 2
    return result // 2

