def count_pairs(n, k, nums):

    # Factorize a number into prime exponents modulo k
    def factorize_mod(num, k):
        if num == 1:
            return {}

        prime_factors = {}
        divisor = 2
        while divisor * divisor <= num:
            count = 0
            while num % divisor == 0:
                num //= divisor
                count += 1
            if count > 0:
                prime_factors[divisor] = count % k
            divisor += 1

        if num > 1:
            prime_factors[num] = 1 % k

        return prime_factors

    result = 0

    # Check all pairs of numbers
    for i in range(n):
        for j in range(i + 1, n):
            a = nums[i]
            b = nums[j]

            # Get signatures
            sig_a = factorize_mod(a, k)
            sig_b = factorize_mod(b, k)

            # Check if product is a k-th power
            is_valid = True
            for prime in set(sig_a.keys()) | set(sig_b.keys()):
                if (sig_a.get(prime, 0) + sig_b.get(prime, 0)) % k != 0:
                    is_valid = False
                    break

            if is_valid:
                result += 1

    return result

