for i in range(n):
    current = a[i]
    target_pos = current - 1  # 0-indexed

    if a[i] == i + 1:
        continue

    # Find where the element that should be at i is
    while a[target_pos] != i + 1:
        # Find a prime distance to move
        found = False

        # Try to move towards i
        if target_pos < i:
            # Move target_pos to the right
            for j in range(target_pos + 1, i + 1):
                if is_prime(j - target_pos + 1):
