def smallest_multiple(n, p):
    """Find the smallest multiple of p that is >= n"""
    if p > n:
        return p
    # smallest multiple is ceil(n/p) * p
    return ((n + p - 1) // p) * p

# Find all primes up to 10^6 using Sieve of Eratosthenes
def sieve(limit):
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False
    return [i for i, prime in enumerate(is_prime) if prime]

