    disc = [0] * (n + 1)
    low = [0] * (n + 1)
    time = [1]
    is_bridge = [False] * (n + 1)

    def dfs(u, parent):
        visited[u] = True
        disc[u] = low[u] = time[0]
        time[0] += 1

        for v in graph[u]:
