import sys

def solve():
    # Read input
    time_str = sys.stdin.readline().strip()
    h_str, m_str = time_str.split(':')
    h = int(h_str)
    m = int(m_str)

    # Convert from 24-hour to 12-hour format
    if h > 12:
        h_12 = h - 12
    elif h == 0:
        h_12 = 12
    else:
        h_12 = h

    # Calculate angles
    hour_angle = h_12 * 30 + m * 0.5
    minute_angle = m * 6

    # Handle 360 case (12:00 gives 360, but we need 0)
    if hour_angle == 360:
        hour_angle = 0
    if minute_angle == 360:
        minute_angle = 0

    # Check if angles are integers
    hour_is_int = hour_angle.is_integer()
    minute_is_int = minute_angle.is_integer()

    # Format output
    if hour_is_int and minute_is_int:
        print(f"{int(hour_angle)} {int(minute_angle)}")
    elif hour_is_int:
        print(f"{int(hour_angle)} {minute_angle}")
    elif minute_is_int:
        print(f"{hour_angle} {int(minute_angle)}")
    else:
        print(f"{hour_angle} {minute_angle}")

if __name__ == "__main__":
    solve()
"}

