    # Brute force: try all combinations of rows
    min_strokes = float('inf')

    # Try all combinations of rows (0 to 255, where each bit represents a row)
    for row_mask in range(256):
        # Paint rows indicated by row_mask
        painted_rows = set()
        for row_idx in range(8):
