                painted_rows.add(row_idx)

        # Check which columns need to be painted
        cols_needed = 0
        for col_idx in range(8):
            # Check if this column still needs painting
            needs_paint = True
            for row_idx in range(8):
                if row_idx in painted_rows:
                    # This square is already black from a row stroke
                    continue
                if board[row_idx][col_idx] == 'B':
                    needs_paint = False
                    break
            if needs_paint:
                cols_needed += 1

        min_strokes = min(min_strokes, len(painted_rows) + cols_needed)

    print(min_strokes)

