def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

def get_order(p, n):
    """Get the lexicographical order number of permutation p"""
    used = [False] * n
    result = 0
    for i in range(n):
        count = 0
        for j in range(n):
            if not used[j] and p[i] > j:
                count += 1
        result += count * factorial(n - 1 - i)
        used[p[i]] = True
    return result

def get_perm(x, n):
    """Get the x-th lexicographical permutation of size n"""
    used = [False] * n
    result = [0] * n
    for i in range(n):
        fact = factorial(n - i - 1)
        index = x % (n - i)
        # Find the index-th unused number
        for j in range(n):
            if not used[j] and index == 0:
                result[i] = j
                used[j] = True
                break
            if not used[j]:
                index -= 1
    return result

n = int(input())
p = list(map(int, input().split()))
q = list(map(int, input().split()))

ord_p = get_order(p, n)
ord_q = get_order(q, n)
total = (ord_p + ord_q) % factorial(n)

result = get_perm(total, n)

print(' '.join(map(str, result)))
