import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = list(map(int, data[1:1+n]))

    # First pass: left to right
    a = m[:]
    for i in range(1, n):
        if a[i] < a[i-1]:
            a[i] = a[i-1]

    # Second pass: right to left
    for i in range(n-2, -1, -1):
        if a[i] < a[i+1]:
            a[i] = a[i+1]

    print(' '.join(map(str, a)))

if __name__ == "__main__":
    solve()
"}

