import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = list(map(int, data[1:1+n]))

    # First assignment
    a = m[:]

    # Left to right pass to avoid valleys
    for i in range(1, n-1):
        if a[i] < a[i-1] and a[i] < a[i+1]:
            # We have a valley at position i
            # Set a[i] to the minimum of its neighbors to avoid valley
            a[i] = min(a[i-1], a[i+1])

    print(' '.join(map(str, a)))

if __name__ == "__main__":
    solve()
"}

