# Function to convert a number to base k
def to_base_k(n, k):
    if n == 0:
        return '0'
    digits = []
    while n > 0:
        digits.append(str(n % k))
        n = n // k
    return ''.join(reversed(digits))

# Generate multiplication table
for i in range(1, k):
    row = []
    for j in range(1, k):
        product = i * j
        row.append(to_base_k(product, k))
    print(' '.join(row))
