m = int(input())
operations = []
current_length = 0

for _ in range(m):
    parts = input().split()
    if parts[0] == '1':
        val = int(parts[1])
        operations.append(('type1', val))
        current_length += 1
    else:
        li = int(parts[1])
        ci = int(parts[2])
        operations.append(('type2', li, ci))
        current_length += ci * li

n = int(input())
queries = list(map(int, input().split()))

for k in queries:
    pos = k
    for op in reversed(operations):
        if op[0] == 'type1':
            # This position is in this Type 1 operation
            if op[1] == pos:
                print(op[1])
                break
        else:
            # Type 2 operation: (li, ci)
            li, ci = op[1], op[2]
            if pos > li:
                # This position comes from the copied part
                copy_idx = (pos - 1) % li
                pos = copy_idx + 1
            else:
                # This position is in the original prefix
                pos = pos
    else:
        # If we didn't find it (shouldn't happen)
        print(pos)
