import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    idx = 1

    result = []

    for i in range(n):
        x = int(data[idx])
        y = int(data[idx + 1])
        idx += 2

        # Move to (x, y)
        if x > 0:
            result.append(f"1 1 R")
        elif x < 0:
            result.append(f"1 1 L")

        if y > 0:
            result.append(f"1 1 U")
        elif y < 0:
            result.append(f"1 1 D")

        result.append("2")  # Pick up bomb

        # Move back to (0, 0)
        if x > 0:
            result.append(f"1 1 L")
        elif x < 0:
            result.append(f"1 1 R")

        if y > 0:
            result.append(f"1 1 D")
        elif y < 0:
            result.append(f"1 1 U")

        result.append("3")  # Destroy bomb


    sys.stdout.write(str(len(result)) + "\n")
