import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    results = []
    idx = 1

    for _ in range(n):
        row = []
        for j in range(n):
            x = int(data[idx])
            y = int(data[idx + 1])
            idx += 2
            row.append((x, y))
        results.append(row)

    # Create the board
    board = [['' for _ in range(n)] for _ in range(n)]

    # For each cell, determine its instruction
    for r in range(n):
        for c in range(n):
            x, y = results[r][c]

            # If we end at (x, y)
            if x != -1 and y != -1:
                # If (x, y) is the same as (r, c), it's X
                if x == r + 1 and y == c + 1:
                    board[r][c] = 'X'
                else:
                    # Determine which direction to point to (x, y)
                    if x == r + 1:
                        board[r][c] = 'D'
                    elif x == r - 1:
                        board[r][c] = 'U'
                    elif y == c + 1:
                        board[r][c] = 'R'
                    elif y == c - 1:
                        board[r][c] = 'L'

            # If we loop infinitely
            elif x == -1 and y == -1:
                board[r][c] = 'X'  # We can mark as X for now

    # Verify if the board is consistent
    for r in range(n):
        for c in range(n):
            ch = board[r][c]

            if ch == 'X':
                continue  # X stays, no move

            # Get the next cell
            if ch == 'D':
                next_r, next_c = r + 1, c
            elif ch == 'U':
                next_r, next_c = r - 1, c
            elif ch == 'R':
                next_r, next_c = r, c + 1
            elif ch == 'L':
                next_r, next_c = r, c - 1
            else:
                next_r, next_c = r, c  # should never happen

            # Check if the path is consistent
            if board[next_r][next_c] == 'X':
                # This cell should end at (r+1, c) or (r-1, c) or (r, c+1) or (r, c-1)
                expected_x = r + 1 if ch == 'D' else r - 1 if ch == 'U' else r else r
                expected_y = c + 1 if ch == 'R' else c - 1 if ch == 'L' else c else c

                if results[r][c][0] != expected_x or results[r][c][1] != expected_y:
