    h, w = map(int, input().split())
    r = list(map(int, input().split()))
    c = list(map(int, input().split()))

    # Check consistency: if r_i > 0 and c_j > 0 at (i, 0) or (0, j)
    for i in range(h):
        if r[i] > 0 and c[0] > 0:
            # Cell (i, 0) must be full from both row i and column 0
            # Check if r_i >= c_0
            if r[i] < c[0]:
                print(0)
                return
            if r[i] > c[0]:
                print(0)
                return

    for j in range(w):
        if c[j] > 0 and r[0] > 0:
            # Cell (0, j) must be full from both column j and row 0
            # Check if c_j >= r_0
            if c[j] < r[0]:
                print(0)
                return
            if c[j] > r[0]:
                print(0)
                return

    # Count free cells
    free_cells = 0
    for i in range(h):
        for j in range(w):
            must_be_full = False

            # Check if cell (i, j) must be full
            if r[i] > 0 and j < r[i]:
                must_be_full = True
            if c[j] > 0 and i < c[j]:
                must_be_full = True

            if not must_be_full:
                free_cells += 1

    # Answer is 2^free_cells % MOD
    print(pow(2, free_cells, MOD))

solve()

