def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        s = input().strip()
        t_str = input().strip()

        # Check if we can convert s to t
        if sorted(s) != sorted(t_str):
            print(-1)
        elif s == t_str:
            print(0)
        else:
            # Find the longest prefix of t that matches s
            l = 0
            while l < n and s[l] == t_str[l]:
                l += 1

            # The minimum number of operations is n - l
            # This works because we can rotate the remaining part to match
            print(n - l)

solve()
