def is_lucky(n):
    """Check if a number is lucky (only contains digits 4 and 7)."""
    s = str(n)
    for ch in s:
        if ch not in {'4', '7'}:
            return False
    return True

def generate_lucky_numbers(limit=10**9):
    """Generate all lucky numbers up to the given limit."""
    lucky = []
    queue = ['4', '7']
    while queue:
        num_str = queue.pop(0)
        num = int(num_str)
        if num <= limit:
            lucky.append(num)
            queue.append(num_str + '4')
            queue.append(num_str + '7')
    return sorted(lucky)

# Generate all lucky numbers
lucky = generate_lucky_numbers()

def count_pairs(pl, pr, vl, vr, k):
    """Count how many (p, v) pairs have exactly k lucky numbers in [min(p, v), max(p, v)]."""
    count = 0
    for p in range(pl, pr + 1):
        for v in range(vl, vr + 1):
            l = min(p, v)
            r = max(p, v)

            # Count lucky numbers in [l, r]
            left = bisect.bisect_left(lucky, l)
            right_idx = bisect.bisect_right(lucky, r)
            lucky_count = right_idx - left

            if lucky_count == k:
                count += 1
    return count

