def parse_structure(s):
    """Parse the corporation structure string into a tree and return names."""
    names = []
    current = None
    i = 0

    while i < len(s):
        if s[i] == ':':
            # Start of subordinates
            if current is not None:
                names.append(current)
            current = None
            i += 1
        elif s[i] == '.':
            # End of this employee
            if current is not None:
                names.append(current)
            current = None
            i += 1
        elif s[i] == ',':
            # Separator between subordinates
            if current is not None:
                names.append(current)
            current = None
            i += 1
        else:
            # Collect the name
            if current is None:
                current = ''
            current += s[i]
            i += 1

    # Build the tree
    employees = {}  # Map from name to list of employee nodes

    # Process names in reverse order
    names = list(reversed(names))

    for name in names:
        # The current employee node
        employee = {'name': name, 'subordinates': []}
        employees[name] = employee

        # Find the parent
        if len(names) > 0:
            parent_name = names[0]
            parent = employees[parent_name]
            parent['subordinates'].append(employee)
            names.pop(0)

    return employees, names


def count_uncomfortable_pairs(root):
    """Count uncomfortable pairs in the tree."""
    count = 0

    # Traverse the tree
    def traverse(employee):
        nonlocal count

        # For each subordinate, if name matches, count
        for sub in employee['subordinates']:
            if sub['name'] == employee['name']:
                count += 1
            traverse(sub)

    traverse(root)
    return count


def main():
    s = input().strip()

    # Parse the structure
    employees, names = parse_structure(s)

    # The root is the first name in the names list
    if employees and names:
        root = employees[names[0]]
        result = count_uncomfortable_pairs(root)
        print(result)
    else:
        print(0)

if __name__ == "__main__":
    main()
