import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    p = int(data[0])
    k = int(data[1])

    # Find coefficients a_i such that a₀ - a₁k + a₂k² - ... = p
    # And all 0 ≤ a_i < k

    coefficients = []
    while p > 0:
        # Find remainder
        rem = p % k
        coefficients.append(rem)
        p //= -k

    # If we ended with a non-zero p, we might need to adjust
    if p != 0:
        # We need to add a coefficient to make it work
        # Let's add 1 to the last coefficient and adjust
        if coefficients:
            coefficients[-1] += k
            coefficients[-1] %= k
            p = (p + 1) % k
        else:
            # Add a coefficient of 1
            coefficients.append(1)

    # Check if the result is correct
    result = 0
    for i, coeff in enumerate(coefficients):
        if i % 2 == 0:
            result += coeff * (k ** i)
        else:
            result -= coeff * (k ** i)

    if result != p:
        print(-1)
    else:
        print(len(coefficients))
        print(' '.join(map(str, coefficients)))

if __name__ == '__main__':
