def get_previous_numbers(n, p):
    """Get all possible previous numbers that could lead to n using prime p"""
    previous = []

    # Case 1: previous number was already a multiple of p
    previous.append(n)

    # Case 2: previous number was not a multiple of p
    for prev in range(n // p, n):
        if prev % p != 0:
            # Applying the rule with prime p to prev should give us n
            # The next number should be the smallest multiple of p ≥ prev
            # That should be ((prev + p - 1) // p) * p
            next_num = ((prev + p - 1) // p) * p
            if next_num == n:
