n, s, l = map(int, input().split())
a = list(map(int, input().split()))

# Use a sliding window to find valid subarrays
from collections import deque

max_deque = deque()
min_deque = deque()

dp = [float('inf')] * (n + 1)
dp[0] = 0  # 0 numbers need 0 pieces

for right in range(1, n + 1):
    # Add a[right-1] to the window
    while max_deque and a[max_deque[-1]] <= a[right-1]:
        max_deque.pop()
    max_deque.append(right-1)

    while min_deque and a[min_deque[-1]] >= a[right-1]:
        min_deque.pop()
    min_deque.append(right-1)

    # Maintain max-min <= s
    while a[max_deque[0]] - a[min_deque[0]] > s:
        if max_deque[0] == right-1:
            max_deque.popleft()
        if min_deque[0] == right-1:
            min_deque.popleft()

    # Now check all possible lefts where window is valid and has length >= l
    left = right - 1
    while left >= 0 and a[max_deque[0]] - a[min_deque[0]] <= s:
        if right - left >= l:
            dp[right] = min(dp[right], dp[left] + 1)
        left -= 1

if dp[n] == float('inf'):
    print(-1)
else:
    print(dp[n])
